const $=s=>document.querySelector(s),main=$('#main'),modal=$('#modal');let page='check',scene='general',file=null,fileURL=null,processing=false,report=null,quizIndex=0,quizAnswered=null,quizScore=0,quizMistakes=[],pollController=null;let realMode=localStorage.getItem('qinan-real-mode')==='true';let contacts=read('qinan-contacts',[]),history=read('qinan-demo-history',[]);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}function save(key,val){try{localStorage.setItem(key,JSON.stringify(val));return true}catch{toast('保存失败，请检查浏览器存储设置');return false}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function openModal(html){$('#modalBody').innerHTML=html;modal.showModal()}$('.modal-close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
function heading(label,title,desc){return `<div class="page-heading"><span class="eyebrow">${label}</span><h1>${title}</h1><p>${desc}</p></div>`}function waveform(){return `<div class="waveform" aria-hidden="true">${Array.from({length:28},(_,i)=>`<span style="height:${10+Math.sin(i*2.4)**2*31}px;animation-delay:${-i*.14}s"></span>`).join('')}</div>`}
