const pageNames={check:'检查材料',contacts:'联系家人',practice:'情景练习',history:'核验记录',report:'核验报告'};
function navigate(){const next=location.hash.slice(1)||'check';page=pageNames[next]?next:'check';if(page==='report'&&!report)page='history';$('#crumb').textContent=pageNames[page];document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));main.className='page-enter';void main.offsetWidth;if(page==='check')renderHome();if(page==='contacts')renderContacts();if(page==='practice')renderQuiz();if(page==='history')renderHistory();if(page==='report')renderReport();window.scrollTo({top:0,behavior:'instant'})}window.addEventListener('hashchange',navigate);
function go(p){if(location.hash==='#'+p)navigate();else location.hash=p}
function renderHome(){const today=new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',timeZone:'Asia/Shanghai'}).format(new Date());main.innerHTML=`<div class="page-intro"><div><p class="eyebrow">A LITTLE CHECK. A LOT OF PEACE.</p><h1>每一份在意，都值得安心。</h1></div><div class="page-date">${icon('calendar')}<span>${today.replace('/','月')}日 · 宜多一份核实</span></div></div><section class="hero"><div class="hero-grid"></div><div class="hero-copy"><div class="hero-tag"><span></span> YOUR PERSONAL PEACE-OF-MIND COMPANION</div><h2>眼见，不一定为实。<br>在意，<span class="outline-word">值得被守护。</span></h2><p>一段声音、一张照片、一条消息。<br>让科技帮你多看一步，让关心的人少担心一点。</p><div class="hero-buttons"><button class="primary" id="startCheck">开始核验材料 ${icon('arrow')}</button><button class="text-button" id="watchDemo"><span class="play-circle">▶</span>看看它如何工作</button></div><div class="hero-bottom"><span>${icon('lock')} 隐私优先设计</span><i></i><span>${icon('scan')} 多模态交叉核验</span><i></i><span>${icon('heart')} 为你在意的人</span></div></div><div class="core-scene" id="coreScene"><div class="core-coord">QINAN / SECURITY CORE V.01</div><div class="orbit"></div><div class="orbit two"></div><div class="core-object" id="coreObject"><div class="shield-back"></div><div class="shield-face"><div class="shield-glyph">${icon('shield')}</div></div></div><div class="core-label label-one">${icon('scan')} 让伪装，无处藏身</div><div class="core-label label-two">${icon('check')} 多一份核实 · 多一份安心</div>${Array.from({length:12},(_,i)=>`<span class="signal-particle" style="left:${15+i*6}%;top:${40+i%4*13}%;animation-delay:-${i*.85}s"></span>`).join('')}<div class="core-caption">DESIGNED TO PROTECT WHAT MATTERS.</div></div><span class="corner-cross">+</span></section><div class="ticker"><span class="ticker-label">${icon('spark')} 安心，从这一步开始</span><span class="ticker-divider"></span><div class="ticker-track"><span>${icon('sound')} 声音合成线索</span><span>${icon('video')} 视频画面核验</span><span>${icon('image')} 图片生成检测</span><span>${icon('chat')} 聊天风险分析</span></div></div><div class="section-heading" id="uploadAnchor"><div class="section-title"><span class="step-index">01</span><h2>把疑问交给亲安</h2></div><span>不急着相信，先一起看看</span></div><div class="work-grid"><section class="upload-card"><div class="mode-tabs" role="tablist" aria-label="核验材料类型"><button class="mode-tab ${scene==='general'?'active':''}" role="tab" aria-selected="${scene==='general'}" data-scene="general">${icon('video')} 声音 / 视频 / 照片</button><button class="mode-tab ${scene==='chat'?'active':''}" role="tab" aria-selected="${scene==='chat'}" data-scene="chat">${icon('chat')} 聊天截图</button></div><div class="dropzone" id="dropzone" role="button" tabindex="0" aria-label="选择或拖放需要检查的材料"></div><div id="fileError" class="error-inline" role="alert"></div><div class="upload-meta"><span>${icon('lock')} ${realMode?'原始材料处理后删除':'演示模式 · 文件不会上传'}</span><button class="primary" id="analyzeButton" disabled>帮我检查 ${icon('arrow')}</button></div></section><aside class="safety-card"><div class="safety-top"><span>A GENTLE REMINDER</span>${icon('heart')}</div><h3>真正的关心，<br>经得起一次<span>确认。</span></h3><p>遇到借钱、转账或索要验证码，<br>先停一停，用熟悉的号码联系家人。</p><button class="family-link" id="familyLink">${icon('phone')} 联系我的家人 ${icon('arrow')}</button><div class="family-avatars"><span class="mini-avatar">爸</span><span class="mini-avatar">妈</span><span class="mini-avatar">你</span><span>把安心，留给最亲的人</span></div></aside></div><div class="journey"><div class="journey-card"><span class="journey-num">01 /</span><div><h3>上传一份材料</h3><p>声音、视频、照片或聊天截图</p></div>${icon('upload')}</div><div class="journey-card"><span class="journey-num">02 /</span><div><h3>看懂核验线索</h3><p>分开检查，用简单的话告诉你</p></div>${icon('scan')}</div><div class="journey-card"><span class="journey-num">03 /</span><div><h3>与本人再次确认</h3><p>用保存的号码，听见真实的回应</p></div>${icon('heart')}</div></div><div class="bottom-section"><span>TECHNOLOGY WITH A HUMAN HEART.</span><button id="sampleButton">还没有材料？体验一个示例 ${icon('arrow')}</button></div>`;
$('#startCheck').onclick=()=>{$('#uploadAnchor').scrollIntoView({behavior:'smooth',block:'center'});$('#dropzone').focus({preventScroll:true})};$('#watchDemo').onclick=demoModal;$('#sampleButton').onclick=demoModal;$('#familyLink').onclick=()=>go('contacts');document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{if(processing)return;scene=b.dataset.scene;clearFile();renderHome()});$('#analyzeButton').onclick=analyze;const dz=$('#dropzone');dz.onclick=e=>{if(!e.target.closest('.remove-file')&&!e.target.closest('video,audio'))chooseFile()};dz.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();chooseFile()}};dz.ondragover=e=>{e.preventDefault();dz.classList.add('dragover')};dz.ondragleave=()=>dz.classList.remove('dragover');dz.ondrop=e=>{e.preventDefault();dz.classList.remove('dragover');if(e.dataTransfer.files.length!==1){$('#fileError').textContent='每次检查一份材料，请选择一个文件。';return}setFile(e.dataTransfer.files[0])};renderFile();const core=$('#coreScene');core.onpointermove=e=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches||document.body.classList.contains('is-paused'))return;const r=core.getBoundingClientRect();$('#coreObject').style.translate=`${(e.clientX-r.left-r.width/2)*.035}px ${(e.clientY-r.top-r.height/2)*.035}px`};core.onpointerleave=()=>{$('#coreObject').style.translate='0 0'};}
function chooseFile(){if(processing)return;$('#fileInput').accept=scene==='chat'?'.jpg,.jpeg,.png,.webp':'.mp4,.mov,.avi,.webm,.wav,.mp3,.m4a,.flac,.ogg,.jpg,.jpeg,.png,.webp';$('#fileInput').value='';$('#fileInput').click()}$('#fileInput').onchange=e=>{if(e.target.files[0])setFile(e.target.files[0])};
function clearFile(){file=null;if(fileURL)URL.revokeObjectURL(fileURL);fileURL=null}function setFile(f){const ext=f.name.split('.').pop().toLowerCase();const allowed=scene==='chat'?['jpg','jpeg','png','webp']:['mp4','mov','avi','webm','wav','mp3','m4a','flac','ogg','jpg','jpeg','png','webp'];if(!allowed.includes(ext)){showError(scene==='chat'?'请选择 JPG、PNG 或 WebP 聊天截图。':'暂不支持此文件类型，请上传常用图片、音频或视频。');return}if(f.size>104857600){showError('文件超过 100MB，请压缩后重试。');return}clearFile();file=f;fileURL=URL.createObjectURL(f);if($('#fileError'))$('#fileError').textContent='';renderFile();if(f.type.startsWith('video/')){const v=document.createElement('video');v.preload='metadata';v.src=fileURL;v.onloadedmetadata=()=>{if(v.duration>180){clearFile();renderFile();showError('视频超过 3 分钟，请截取需要核验的片段。')}v.removeAttribute('src');v.load()}}}
function showError(text){if($('#fileError'))$('#fileError').textContent=text;else toast(text)}
function renderFile(){if(!$('#dropzone'))return;$('#analyzeButton').disabled=!file||processing;if(!file){$('#dropzone').innerHTML=`<span class="upload-symbol">${icon('upload')}</span><h3>拖放材料到这里，或<span>点击上传</span></h3><p>${scene==='chat'?'JPG / PNG / WEBP':'MP4 / MOV / MP3 / WAV / JPG / PNG 等'} · 最大 100MB${scene==='general'?' · 视频不超过 3 分钟':''}</p>`;return}let media=file.type.startsWith('image/')?`<img class="file-preview" src="${fileURL}" alt="所选材料预览">`:file.type.startsWith('video/')?`<video class="file-preview" controls src="${fileURL}"></video>`:file.type.startsWith('audio/')?`<audio class="file-preview" controls src="${fileURL}"></audio>`:`<span class="upload-symbol">${icon('file')}</span>`;$('#dropzone').innerHTML=`<button class="icon-btn remove-file" id="removeFile" aria-label="移除文件">${icon('close')}</button>${media}<span class="selected-name">${esc(file.name)}</span><p style="margin-top:7px">${(file.size/1024/1024).toFixed(2)} MB · 点击可更换材料</p>`;$('#removeFile').onclick=e=>{e.stopPropagation();clearFile();renderFile()}}
function demoModal(){openModal(`<span class="modal-eyebrow">MEET YOUR PEACE-OF-MIND COMPANION</span><h2>先体验一次，再放心使用。</h2><p>如果收到了“家人”发来的借钱语音，你会怎么做？<br>跟随这个虚构情景，看看亲安如何帮助你找到核实的方向。</p><div class="sample-card">${icon('sound')}<div><h3>“妈，我换号码了，急用一笔钱…”</h3><small>虚构情景 · 交互演示 · 非真实检测</small></div>${waveform()}</div><p class="warning">示例报告用于展示交互，不代表模型实测结果。</p><div class="modal-actions"><button class="primary" id="runDemo">体验核验过程 ${icon('arrow')}</button><button class="text-button" id="skipDemo">先看看操作说明</button></div>`);$('#runDemo').onclick=()=>{modal.close();startDemo('亲人求助语音 · 虚构示例',true)};$('#skipDemo').onclick=helpModal}
function loadingView(isDemo,message='正在分开检查材料…'){main.innerHTML=heading('VERIFICATION IN PROGRESS','先别着急，我们一起看看。','核验提供线索，身份仍需使用熟悉的号码再次确认。')+`<div class="surface empty-state"><div class="loading-scan">${icon('scan')}</div><span class="report-badge">${isDemo?'演示流程 · 非真实检测':'真实接口任务'}</span><h3 id="progressTitle">${message}</h3><p id="progressMessage">${isDemo?'正在展示核验过程，所选文件不会上传或送入模型。':'正在等待后端处理，请保留当前页面。'}</p><div class="waveform" style="max-width:260px;margin:28px auto">${Array.from({length:30},(_,i)=>`<span style="height:${8+Math.sin(i*1.5)**2*33}px;animation-delay:${-.13*i}s"></span>`).join('')}</div></div>`}
async function startDemo(name,example=false){if(processing)return;processing=true;page='check';if(location.hash!=='#check')location.hash='check';await new Promise(r=>setTimeout(r,0));loadingView(true);const demoStages=['正在展示声音线索…','正在整理独立核实建议…','演示报告已准备好'];for(const text of demoStages){await new Promise(r=>setTimeout(r,900));if($('#progressTitle'))$('#progressTitle').textContent=text}processing=false;report={id:'demo-'+Date.now(),name,date:new Date().toISOString(),demo:true,example};history.unshift(report);history=history.slice(0,30);save('qinan-demo-history',history);go('report')}
async function analyze(){if(!file||processing)return;if(!realMode){await startDemo(file.name);return}processing=true;const fd=new FormData();fd.append('file',file);fd.append('scene',scene);fd.append('context','');loadingView(false,'正在提交材料…');try{const r=await fetch('/api/analyze',{method:'POST',body:fd});if(!r.ok)throw new Error('材料提交失败，请检查后端连接后重试。');const job=await r.json();if(!job.job_id)throw new Error('后端未返回任务编号，请检查接口。');sessionStorage.setItem('qinan-active-job',job.job_id);await pollJob(job.job_id)}catch(e){processing=false;renderHome();showError(e.message)}}
async function pollJob(id){let fails=0;for(let i=0;i<800;i++){await new Promise(r=>setTimeout(r,1500));let job;try{const r=await fetch('/api/jobs/'+encodeURIComponent(id));if(!r.ok)throw Error();job=await r.json();fails=0}catch{if(++fails>=3)throw new Error('暂时无法连接后端。任务编号已保留，稍后可恢复检查或查看核验记录。');continue}if($('#progressTitle'))$('#progressTitle').textContent=job.message||'正在等待检测结果…';if(job.status==='failed'){sessionStorage.removeItem('qinan-active-job');throw new Error(job.error||job.message||'本次检查未能完成。')}if(job.status==='completed'&&job.result){sessionStorage.removeItem('qinan-active-job');report={...job.result,demo:false};processing=false;go('report');return}}throw new Error('等待时间较长，任务仍可能在后台处理，请稍后从核验记录查看。')}
function renderContacts(){main.innerHTML=heading('YOUR CIRCLE OF TRUST','熟悉的声音，才是安心的答案。','提前保存家人的真实号码。遇到紧急请求，先打一个电话。')+`<div class="contact-layout"><section class="surface"><h2>我的家人 <span style="color:#9daf88;font-size:11px">/ ${contacts.length}</span></h2><div id="contactList"></div></section><section class="surface"><span class="decor-star">✳</span><h2>把最重要的人，放在这里。</h2><p class="mode-explanation">请与家人事先确认号码，不要使用可疑消息中提供的新号码。</p><form id="contactForm"><div class="form-field"><label for="contactName">怎么称呼 TA</label><input id="contactName" placeholder="例如：女儿、小陈" required maxlength="30" autocomplete="off"></div><div class="form-field"><label for="contactPhone">熟悉的电话号码</label><input id="contactPhone" placeholder="请输入已确认的号码" type="tel" required maxlength="25" pattern="\+?[\d \-]{5,25}" autocomplete="tel"></div><button class="primary" type="submit">保存家人号码 ${icon('heart')}</button></form></section></div><div class="notice">${icon('lock')} 联系人仅保存在当前设备的浏览器中。拨号按钮会打开设备的电话程序，手机使用更方便。</div>`;renderContactList();$('#contactForm').onsubmit=e=>{e.preventDefault();const name=$('#contactName').value.trim(),phone=$('#contactPhone').value.trim();if(!name||!/^\+?[\d -]{5,25}$/.test(phone)){toast('请填写称呼和有效电话号码');return}const next=[...contacts,{name,phone}];if(save('qinan-contacts',next)){contacts=next;renderContactList();$('#contactForm').reset();toast('家人的号码已保存，安心多了一份')}}}
function renderContactList(){const el=$('#contactList');if(!contacts.length){el.innerHTML=`<div class="empty-state">${icon('heart')}<h3>给关心的人，留个位置。</h3><p>还没有保存联系人。<br>先添加一位家人，核实时就能快速找到 TA。</p></div>`;return}el.innerHTML=contacts.map((c,i)=>`<div class="contact-row"><span class="avatar">${esc(c.name.charAt(0))}</span><div><h3>${esc(c.name)}</h3><p>${esc(c.phone)}</p></div><a href="tel:${c.phone.replace(/[^+\d]/g,'')}" aria-label="拨打${esc(c.name)}的电话">${icon('phone')}</a><button class="icon-btn" data-remove="${i}" aria-label="移除${esc(c.name)}">${icon('trash')}</button></div>`).join('');el.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const i=+b.dataset.remove;openModal(`<span class="modal-eyebrow">YOUR CIRCLE OF TRUST</span><h2>移除这个号码？</h2><p>将从当前浏览器移除 ${esc(contacts[i].name)} 的联系方式。</p><div class="modal-actions"><button class="primary" id="confirmRemove">确认移除</button><button class="secondary" id="cancelRemove">保留号码</button></div>`);$('#confirmRemove').onclick=()=>{const next=contacts.filter((_,j)=>j!==i);if(save('qinan-contacts',next)){contacts=next;modal.close();renderContactList();toast('联系人已移除')}};$('#cancelRemove').onclick=()=>modal.close()})}
const quiz=[{title:'“妈，我换号码了。”',text:'一个陌生号码发来消息：“妈，我是你儿子，手机坏了，先帮我转 3000 元，着急！”',answers:['马上转账，孩子的事不能耽误','拨打原来保存的号码，向本人核实','问对方是不是本人，收到“是”就转账'],correct:1,why:'称呼和语气都可能被模仿。请通过原来保存的号码或其他独立渠道核实身份。'},{title:'视频里的人，一定是本人吗？',text:'“家人”在视频中请求转账，但画面只有短短几秒，对方说信号不好，拒绝再次通话。',answers:['看到脸就放心转账','索要一张身份证照片','暂停转账，通过熟悉号码再次联系'],correct:2,why:'视频画面也可能被合成或替换。短视频不能证明身份，应该独立联系本人。'},{title:'验证码可以告诉“客服”吗？',text:'来电自称平台客服，说要帮你取消付费服务，需要你读出收到的短信验证码。',answers:['不提供验证码，通过官方渠道核实','对方知道我的名字，应该可信','先说一半验证码'],correct:0,why:'验证码与账户和资金安全有关。不要提供给来电者，请自行打开官方应用或拨打官方电话核实。'},{title:'“安全账户”真的安全吗？',text:'来电者自称执法人员，要求你把钱转入“安全账户”，并强调不能告诉家人。',answers:['配合转账，证明清白','挂断电话，自行联系官方机构核实','让对方发证件就转账'],correct:1,why:'要求转入所谓“安全账户”并阻止你与他人核实，是需要警惕的线索。不要转账，应自行查找官方联系方式。'},{title:'熟人的语音消息，可以放心吗？',text:'好友发来语音：“帮我代付一下，不方便打电话。”声音和本人很像。',answers:['先付款再打电话','根据声音判断，像本人就行','通过其他熟悉渠道联系本人，核实请求'],correct:2,why:'声音可以被克隆。即使声音熟悉，涉及付款时也应通过独立渠道核实。'},{title:'收到可疑链接，先做什么？',text:'一条短信称你有包裹滞留，点击链接填写银行卡信息即可领取。',answers:['自行打开官方快递应用核实','链接看起来很正规，直接填写','转给家人，让家人帮忙填写'],correct:0,why:'不要从陌生短信进入页面填写个人或银行卡信息。请自行打开官方应用查询。'}];
function renderQuiz(){if(quizIndex>=quiz.length){main.innerHTML=heading('A LITTLE PRACTICE. A STRONGER YOU.','多练习一次，多一份从容。','你已完成本轮情景练习。这里是虚构学习情景，并非真实案件原文。')+`<section class="surface question-card"><div class="empty-state">${icon('spark')}<h3>本轮答对 ${quizScore} / ${quiz.length} 题</h3><p>${quizScore===quiz.length?'每一次认真核实，都是对家人的守护。':'把这些提醒记在心里，下次就能多一份警觉。'}</p></div>${quizMistakes.map(q=>`<div class="notice" style="margin-bottom:12px"><b>${q.title}</b><br>${q.why}</div>`).join('')}<button class="primary" id="restartQuiz">再练一轮 ${icon('refresh')}</button></section>`;$('#restartQuiz').onclick=()=>{quizIndex=0;quizScore=0;quizAnswered=null;quizMistakes=[];renderQuiz()};return}const q=quiz[quizIndex];main.innerHTML=heading('SPOT THE SIGNS. KEEP YOUR PEACE.','练习识别，让伪装少一点机会。','不必成为专家。记住“先停一停，再核实”，就已经迈出了重要的一步。')+`<section class="surface question-card"><div class="question-meta"><span>情景 ${String(quizIndex+1).padStart(2,'0')} / ${String(quiz.length).padStart(2,'0')}</span><span>已答对 ${quizScore} 题</span></div><div class="progress-track"><span style="width:${quizIndex/quiz.length*100}%"></span></div><h2>${q.title}</h2><div class="question-text">${q.text}</div><p class="eyebrow">你会怎么做？</p>${q.answers.map((a,i)=>`<button class="answer ${quizAnswered!==null?(i===q.correct?'correct':i===quizAnswered?'wrong':''):''}" data-answer="${i}" ${quizAnswered!==null?'disabled':''}><b>${quizAnswered!==null&&i===q.correct?'✓':quizAnswered===i?'✕':String.fromCharCode(65+i)}</b>${a}</button>`).join('')}${quizAnswered!==null?`<div class="question-feedback"><b>${quizAnswered===q.correct?'✓ 这一步，让安心更近了。':'✕ 再多核实一步，会更稳妥。'}</b><br>${q.why}</div><button class="primary" id="nextQuestion">${quizIndex===quiz.length-1?'查看本轮结果':'下一道情景'} ${icon('arrow')}</button>`:''}</section>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(quizAnswered!==null)return;quizAnswered=+b.dataset.answer;if(quizAnswered===q.correct)quizScore++;else quizMistakes.push(q);renderQuiz()});if($('#nextQuestion'))$('#nextQuestion').onclick=()=>{quizIndex++;quizAnswered=null;renderQuiz()}}
async function renderHistory(){main.innerHTML=heading('YOUR JOURNEY TO PEACE OF MIND','每一次核实，都有迹可循。',realMode?'从后端读取实际核验记录。':'这里保存当前浏览器中的演示报告。演示与真实检测始终分开。')+`<section class="surface" id="historyList"></section>`;let items=history;if(realMode){$('#historyList').innerHTML='<p class="mode-explanation">正在读取实际核验记录…</p>';try{const r=await fetch('/api/cases');if(!r.ok)throw Error();const data=await r.json();items=Array.isArray(data)?data:data.items||data.cases||[]}catch{$('#historyList').innerHTML=`<div class="empty-state">${icon('clock')}<h3>暂时无法连接后端。</h3><p>请确认 API 服务已启动，再重试。</p><button class="secondary" id="retryHistory">重新读取</button></div>`;$('#retryHistory').onclick=renderHistory;return}}if(page!=='history')return;if(!items.length){$('#historyList').innerHTML=`<div class="empty-state">${icon('clock')}<h3>你的第一份安心记录，还在路上。</h3><p>检查一份材料，或体验一个虚构示例，<br>完成后的记录会出现在这里。</p><button class="primary" id="firstCheck">开始一次核验 ${icon('arrow')}</button></div>`;$('#firstCheck').onclick=()=>go('check');return}$('#historyList').innerHTML=items.map((r,i)=>`<div class="history-row"><span class="history-icon">${icon('file')}</span><div><h3>${esc(r.name||r.filename||r.file_name||'核验记录')}</h3><small>${esc(new Date(r.date||r.created_at||Date.now()).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))} · ${r.demo?'交互演示，非真实检测':'实际核验记录'}</small></div><button data-report="${i}">查看报告 ↗</button></div>`).join('');document.querySelectorAll('[data-report]').forEach(b=>b.onclick=async()=>{const r=items[+b.dataset.report];if(r.demo){report=r;go('report');return}try{b.disabled=true;const res=await fetch('/api/cases/'+encodeURIComponent(r.id));if(!res.ok)throw Error();report={...await res.json(),demo:false};go('report')}catch{toast('报告暂时无法读取，请稍后再试');b.disabled=false}})}
function renderReport(){if(!report){go('history');return}const demo=report.demo;main.innerHTML=heading('A CLEARER VIEW. A CALMER MIND.',demo?'看见线索，记得再次确认。':'核验完成，请独立确认身份。',esc(report.name||report.filename||report.file_name||'核验报告'))+`<div class="notice mode-notice">${demo?'交互演示报告 · 下方内容为虚构示例，不是对上传文件的真实检测，也不作为身份或诈骗判定。':'本报告来自实际后端。检测提供线索，身份仍需独立核实。'}</div><div class="result-banner">${icon(demo?'scan':'shield')}<div><h2>${demo?'先暂停转账，用熟悉的号码联系本人。':'请结合下方实际结果，再向本人核实。'}</h2><p>${demo?'“更换号码”“急需用钱”“不方便通话”等情景，值得多问一句、多打一个电话。':'各个模块独立提供线索；无法判断的模块不等于安全或危险。'}</p></div></div>${demo?`<div class="result-modules"><section class="surface">${icon('sound')}<h3>声音检查 · 演示</h3>${waveform()}<p>熟悉的声音也可能被克隆。此处波形是装饰性动画，不是文件的真实波形。</p></section><section class="surface">${icon('chat')}<h3>请求核实 · 演示</h3><p style="font-size:14px;color:#6f8657;margin-top:26px;line-height:2">“我换号码了”<br>“急用一笔钱”<br>“现在不方便打电话”</p><p>虚构情景中的请求，需要独立联系本人确认。</p></section><section class="surface">${icon('heart')}<h3>你的下一步</h3><p style="margin-top:26px;line-height:2.5">01 / 暂停转账与付款<br>02 / 不提供验证码<br>03 / 拨打原来保存的号码</p><p>一次确认，胜过匆忙的相信。</p></section></div>`:renderActualModules(report)}<div class="result-actions"><button class="primary" id="reportContacts">联系我的家人 ${icon('phone')}</button><button class="secondary" id="exportReport">下载${demo?'演示':'完整'}记录</button><button class="secondary" id="printReport">打印报告</button><button class="text-button" id="anotherCheck">再检查一份材料 ${icon('arrow')}</button></div>${!demo?`<details class="surface" style="margin-bottom:30px"><summary>完整后端记录 / ${esc(report.id||'')}</summary><pre class="api-raw">${esc(JSON.stringify(report,null,2))}</pre></details>`:''}`;$('#reportContacts').onclick=()=>go('contacts');$('#anotherCheck').onclick=()=>{clearFile();go('check')};$('#printReport').onclick=()=>window.print();$('#exportReport').onclick=()=>{const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`qinan-${demo?'demo-':''}${report.id||'report'}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('报告记录已下载')};}
function renderActualModules(r){const source=r.modules||{};const entries=Array.isArray(source)?source.map((m,i)=>[m.type||m.name||String(i),m]):Object.entries(source);const labels={audio:'声音检查',video:'视频检查',image:'图片检查',chat:'聊天分析'};return `<div class="result-modules">${entries.filter(([k,m])=>k!=='tamper'&&m&&m.status!=='disabled'&&!m.disabled).map(([k,m])=>{const threshold=Number.isFinite(m.threshold)?m.threshold:.5;const valid=m.status==='completed'&&Number.isFinite(m.score);const flag=valid&&(m.score>=threshold||(m.segments||[]).some(s=>Number.isFinite(s.score)&&s.score>=(Number.isFinite(s.threshold)?s.threshold:threshold)));return `<section class="surface">${icon(k==='audio'?'sound':k==='video'?'video':'scan')}<h3>${esc(labels[k]||k)}</h3><p>${valid?(flag?'发现需要进一步核实的线索':'未发现超过本项提醒线的分数，仍需核实'):esc(m.message||m.error||m.reason||'本项无法判断')}</p>${valid?`<p>检测分数：${m.score.toFixed(4)}<br>本项提醒线：${threshold}</p>`:''}<p>检测分数不是诈骗概率，也不能证明说话人的身份。</p></section>`}).join('')}</div>${r.chat_analysis?`<section class="surface" style="margin-bottom:22px"><h2>${esc(r.chat_analysis.assessment?.title||'聊天分析')}</h2><p class="mode-explanation">${esc(r.chat_analysis.assessment?.summary||'请展开完整记录查看实际分析。')}</p>${(r.chat_analysis.signals||[]).map(s=>`<div class="notice" style="margin-top:10px"><b>${esc(s.title)}</b><br><span style="white-space:pre-wrap">${esc(s.quote)}</span></div>`).join('')}</section>`:''}`}
function helpModal(){openModal(`<span class="modal-eyebrow">THREE STEPS TO A LITTLE MORE PEACE</span><h2>安心，其实只需要三步。</h2><div class="steps-help"><div><b>01</b><span>选择一份声音、视频、照片或聊天截图。每次一份，最大 100MB，视频不超过 3 分钟。</span></div><div><b>02</b><span>点击“帮我检查”，查看各个模块提供的线索。演示模式仅展示交互，不检测文件。</span></div><div><b>03</b><span>涉及钱款或验证码，先暂停，用原来保存的号码联系本人。检测不能替代身份核实。</span></div></div><div class="modal-actions"><button class="primary" id="helpDone">知道了，开始核实 ${icon('arrow')}</button></div>`);$('#helpDone').onclick=()=>modal.close()}
function settingsModal(){openModal(`<span class="modal-eyebrow">MAKE YOURSELF AT HOME</span><h2>你的安心空间。</h2><p>选择适合当前环境的工作方式。</p><div class="toggle-row"><span>工作模式</span><div class="pill"><button id="demoMode" class="${!realMode?'active':''}">交互演示</button><button id="realMode" class="${realMode?'active':''}">真实接口</button></div></div><p class="mode-explanation">${realMode?'真实接口会向同源 /api 提交文件，需要自行接入原项目 FastAPI 后端。当前托管预览未附带模型服务。':'交互演示可体验上传、示例报告和练习。选择的文件仅在浏览器本地预览，不上传，不送入检测模型。'}</p><div class="toggle-row"><span>动态效果</span><button class="secondary" id="toggleMotion">${document.body.classList.contains('is-paused')?'恢复动效':'暂停动效'}</button></div><p>家人联系人仅保存在当前设备；不会跨设备同步。</p><div class="modal-actions"><button class="primary" id="settingsDone">完成 ${icon('check')}</button></div>`);$('#demoMode').onclick=()=>setMode(false);$('#realMode').onclick=()=>setMode(true);$('#toggleMotion').onclick=()=>{toggleMotion();settingsModal()};$('#settingsDone').onclick=()=>modal.close()}
function setMode(val){if(processing){toast('请等待当前核验完成');return}realMode=val;localStorage.setItem('qinan-real-mode',String(val));updateMode();settingsModal();navigate()}function toggleMotion(){const paused=document.body.classList.toggle('is-paused');$('#motionButton').innerHTML=icon(paused?'play':'pause');$('#motionButton').title=paused?'恢复动态效果':'暂停动态效果';$('#motionButton').setAttribute('aria-label',paused?'恢复动态效果':'暂停动态效果');localStorage.setItem('qinan-motion-paused',String(paused))}$('#settings').onclick=settingsModal;$('#modeButton').onclick=settingsModal;$('#helpButton').onclick=helpModal;$('#motionButton').onclick=()=>{toggleMotion();toast(document.body.classList.contains('is-paused')?'动态效果已暂停':'动态效果已恢复')};if(localStorage.getItem('qinan-motion-paused')==='true')toggleMotion();navigate();
if(realMode&&sessionStorage.getItem('qinan-active-job')){const id=sessionStorage.getItem('qinan-active-job');openModal(`<h2>继续上次的核验？</h2><p>检测任务编号已保留，可以继续等待后端返回结果。不会重复上传。</p><button class="primary" id="resumeJob">恢复查看 ${icon('arrow')}</button>`);$('#resumeJob').onclick=async()=>{modal.close();processing=true;go('check');await new Promise(r=>setTimeout(r,0));loadingView(false);try{await pollJob(id)}catch(e){processing=false;renderHome();showError(e.message)}}}
window.addEventListener('beforeunload',()=>{if(fileURL)URL.revokeObjectURL(fileURL)});
